insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed for adult learners, as described in a pilot study.','The plan was accepted once the committee had dealt with the risks it found.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in public institutions, as described in a professional workshop.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','Managers blamed a single change because complaints rose quickly.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability during periods of change, as described in a policy review.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although peer feedback was initially criticized, later evidence showed that it could be useful when applied carefully in small communities, as described in a classroom discussion.','The usefulness of peer feedback was accepted before anyone criticized it.','Early criticism proved that peer feedback had no value at all.','Later evidence showed that peer feedback should never be applied.','Later evidence suggested that peer feedback, despite early criticism, may have value if used carefully.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a training program.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','The researchers made a recommendation because the data were complete.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_2", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in an evaluation report.','The author claims feedback is useful only when students stop practicing.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author suggests that practice and feedback are unrelated.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_2", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a committee meeting.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','The process became less transparent after the new system was adopted.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_2", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a student guide.','Future research became unnecessary after the experiment.','The experiment was too large to raise useful questions.','The results were ignored because the experiment was not small.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_2", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction under careful supervision, as described in a pilot study.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage denies that convenience affects service use.','The passage argues that inconvenient services attract the most users.','The passage says convenience always guarantees satisfaction.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_2", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
