insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a training program.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','The writer says popularity and reliability are exactly the same.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although public recycling was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in an evaluation report.','Early criticism proved that public recycling had no value at all.','Later evidence suggested that public recycling, despite early criticism, may have value if used carefully.','The usefulness of public recycling was accepted before anyone criticized it.','Later evidence showed that public recycling should never be applied.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that flexible work hours solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a committee meeting.','The report argues that flexible work hours solves all problems completely.','The report discusses many solutions but never mentions a specific problem.','According to the report, flexible work hours is not a complete solution but may help with a particular problem.','The report rejects the idea that flexible work hours can help in any way.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in small communities, as described in a student guide.','The researchers made a recommendation because the data were complete.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a pilot study.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent under careful supervision, as described in a professional workshop.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was adopted mainly because it reduced costs.','The process became less transparent after the new system was adopted.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_5", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
