insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes after initial trials, as described in a professional workshop.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_6", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in schools, as described in a policy review.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was adopted mainly because it reduced costs.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_6", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research for adult learners, as described in a classroom discussion.','The results were ignored because the experiment was not small.','The experiment was too large to raise useful questions.','Future research became unnecessary after the experiment.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_6", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in a training program.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_7", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in schools, as described in an evaluation report.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','The decline in complaints was sudden and easy to explain.','Managers blamed a single change because complaints rose quickly.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_7", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a committee meeting.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_7", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Although museum apps was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in a student guide.','Early criticism proved that museum apps had no value at all.','Later evidence showed that museum apps should never be applied.','The usefulness of museum apps was accepted before anyone criticized it.','Later evidence suggested that museum apps, despite early criticism, may have value if used carefully.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_7", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that open data solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a pilot study.','According to the report, open data is not a complete solution but may help with a particular problem.','The report argues that open data solves all problems completely.','The report rejects the idea that open data can help in any way.','The report discusses many solutions but never mentions a specific problem.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_7", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
